package com.axelwiston.solarsystemexplorer;
import android.content.Context;import android.graphics.Canvas;import android.graphics.Paint;import android.graphics.RectF;import android.util.AttributeSet;import android.view.MotionEvent;import android.view.View;
public class PlanetOrderView extends View {
 public interface OnOrderCorrectListener{void onOrderCorrect(boolean correct);}
 private final Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);private final String[] names={"Mercury","Venus","Earth","Mars","Jupiter","Saturn","Uranus","Neptune"};private final int[] colors={0xFFB7A18A,0xFFE9B878,0xFF3E91D5,0xFFE45B43,0xFFD9A66B,0xFFE8C778,0xFF72D5D0,0xFF426FE0};private final int[] order={3,0,6,2,7,1,5,4};private final float density;private int dragging=-1;private OnOrderCorrectListener listener;
 public PlanetOrderView(Context c){this(c,null);}public PlanetOrderView(Context c,AttributeSet a){super(c,a);density=getResources().getDisplayMetrics().density;}
 public void setOnOrderCorrectListener(OnOrderCorrectListener l){listener=l;notifyState();}private boolean correct(){for(int i=0;i<8;i++)if(order[i]!=i)return false;return true;}private void notifyState(){if(listener!=null)listener.onOrderCorrect(correct());}
 @Override protected void onDraw(Canvas c){super.onDraw(c);float row=42*density;for(int i=0;i<8;i++){float top=i*row+3*density;p.setColor(i==dragging?0xFF526AA8:0xFF202F5B);c.drawRoundRect(new RectF(4*density,top,getWidth()-4*density,top+row-5*density),10*density,10*density,p);p.setColor(0xFFFFD56A);p.setTextSize(12*density);c.drawText((i+1)+".",15*density,top+25*density,p);p.setColor(colors[order[i]]);c.drawCircle(48*density,top+19*density,10*density,p);p.setColor(0xFFFFFFFF);p.setTextSize(14*density);c.drawText(names[order[i]],68*density,top+25*density,p);p.setTextSize(10*density);p.setColor(0xFFBFD0FF);c.drawText("↕",getWidth()-27*density,top+25*density,p);}}
 @Override public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){dragging=Math.max(0,Math.min(7,(int)(e.getY()/(42*density))));invalidate();return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP&&dragging>=0){int target=Math.max(0,Math.min(7,(int)(e.getY()/(42*density))));if(target!=dragging){int v=order[dragging];if(target>dragging)System.arraycopy(order,dragging+1,order,dragging,target-dragging);else System.arraycopy(order,target,order,target+1,dragging-target);order[target]=v;}dragging=-1;invalidate();notifyState();return true;}if(e.getActionMasked()==MotionEvent.ACTION_CANCEL){dragging=-1;invalidate();return true;}return true;}
}
